const emptyConfig=():SpecialtyConfig=>({primarySkill:null,skills:[],tools:[],requirements:[],memoryRead:[],memoryWrite:[],sharedMemory:false,modes:Object.fromEntries(templateCategories.map(c=>[c,'ask']))});
/** A group name as a heading: "acting_performance_and_presenting" → "Acting performance and presenting". */
const sentence=(s:string)=>{const t=s.replaceAll('_',' ').replace(/\s+/g,' ').trim().toLowerCase();return properWords(t.charAt(0).toUpperCase()+t.slice(1));};
const readable=(s:string)=>s.replace(/^mcp__[^_]+__/,'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const plural=(n:number,word:string)=>`${n} ${word}${n===1?'':'s'}`;
const uuidLike=(id:string)=>/^[a-f0-9-]{36}$/.test(id);
async function rpc<T>(client:SessionClient,method:string,path:string,body?:unknown):Promise<T>{const r=await client.request({method,path,...(body===undefined?{}:{body})} as never);if(r.status!==200)throw Error((r.body as {code?:string})?.code??'unavailable');return r.body as T;}
const draftError=(e:unknown)=>e instanceof Error&&e.message==='local_model_required'?'Girru needs a local model on this computer to draft it. Copy one or start empty instead.':e instanceof Error&&e.message==='draft_busy'?'Your local model is still writing another draft. Try again in a moment.':'Your local model could not write a draft. Try again, or start empty.';
const errorText=(e:unknown)=>e instanceof Error&&['version_conflict','links_changed','impact_confirmation_required'].includes(e.message)?'This specialty or its agents changed. Reload and check again.':e instanceof Error&&['tools_changed','skill_unavailable'].includes(e.message)?'A chosen tool or skill changed. Check Tools and Skills before saving.':e instanceof Error&&e.message==='specialty_limit'?'An agent can have up to ten specialties. Take one back first.':e instanceof Error&&e.message==='name_taken'?'This agent name is already used. Choose another name.':'Could not finish this. Try again.';
function payload(t:Template){return {name:t.name,department:t.department,description:t.description,instructions:t.instructions,config:t.config,revision:t.revision};}
const typing=(t:EventTarget)=>t instanceof HTMLElement&&(!!t.closest('input,textarea,select')||t.isContentEditable);

/**
 * Specialties as a desktop section (boards SP1–SP6): departments in the
 * sidebar, a quiet grouped list, the selected specialty on the right, an open
 * specialty with its parts, and one sheet per decision. Giving and taking
 * back undo; only Update and Hire ask first. Specialties never grant tools.
 */
/** STORE-MAP-01 P2 (AG1): the first line of a description, as agents see it before they open the guide. */
const firstLine=(t:string|null|undefined)=>String(t??'').split('\n').map(l=>l.trim()).find(Boolean)??'';
